<?php require_once '../config.php';require_admin();$customers=db()->query("SELECT c.*,COUNT(o.id) orders,COALESCE(SUM(o.total),0) spent FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id ORDER BY c.id DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>Customers</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header><div class="top"><a class="brand" href="../index.php"><span>📖</span><b>Kalpalatha<small>Customers</small></b></a><div class="links"><a href="index.php">Dashboard</a><a href="logout.php">Logout</a></div></div></header><main class="dash"><section class="tablecard"><h1>Customers</h1><div class="table-scroll"><table><tr><th>Name</th><th>Phone</th><th>Email</th><th>Orders</th><th>Spent</th></tr><?php foreach($customers as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['phone'])?></td><td><?=e($c['email'])?></td><td><?=$c['orders']?></td><td><?=money((float)$c['spent'])?></td></tr><?php endforeach;?></table></div></section></main></body></html>